const staticData = this.getWorkflowStaticData('global');
const now = Date.now();
const TTL_MS = 3 * 60 * 1000;
const fresh = !!(staticData.menuCache && (now - staticData.menuCache.ts) < TTL_MS);
return [{ json: { fresh, cached: fresh ? staticData.menuCache.data : null } }];

const menu = $('GET /api/menu').first().json;
const sizesRaw = $input.first().json;

// Nombre de categoria por id, para desambiguar cuando dos productos de categorias distintas comparten nombre (ej. 'Costillitas BBQ' en pizzas y en especiales)
const categoryNameById = {};
for (const c of menu.categories || []) categoryNameById[c.id] = c.name;

// Deteccion GLOBAL de nombres repetidos (no solo dentro de la misma categoria)
const seen = new Map();
const dupNames = new Set();
for (const p of menu.products || []) {
  if (seen.has(p.nombre)) dupNames.add(p.nombre);
  seen.set(p.nombre, true);
}

const categories = (menu.categories || []).map(c => ({ id: c.id, name: c.name }));

const products = (menu.products || []).map(p => {
  let nombre = p.nombre;
  if (dupNames.has(p.nombre)) {
    // Primero intenta desambiguar por subcategoria; si el producto no tiene subcategoria, cae a la categoria
    nombre = p.subcategory ? (p.nombre + ' (' + p.subcategory + ')') : (p.nombre + ' (' + (categoryNameById[p.categoryId] || p.categoryId) + ')');
  }
  const out = { id: p.id, categoryId: p.categoryId, nombre, descripcion: p.descripcion, basePrice: p.basePrice, vegetariano: p.vegetariano };
  if (p.subcategory) out.subcategory = p.subcategory;
  // Mismo criterio que server/services/orderPricing.js hasRealSizes(): solo los sabores de pizza (no la Porcion individual) aceptan talla
  if (p.categoryId === 'pizzas' && p.subcategory !== 'Porción') out.aceptaTalla = true;
  return out;
});

// Solo variantes activas -- si mañana GastroPro marca una en activo:false, no debe llegar al agente
const variants = (menu.variants || [])
  .filter(v => v.activo !== false)
  .map(v => ({ id: v.id, productoId: v.productoId, nombre: v.nombre, precioModificador: v.precioModificador }));

// pizza_sizes tiene filas legacy duplicadas por nombre con precio distinto (seed viejo
// scripts/seed-menu.sql, ids 'psz_*') mezcladas con el seed vigente (server/seedData/
// juanchosMenu.js, ids sin prefijo: small/junior/mediana/familiar). Se filtran las
// legacy por prefijo de id para no ofrecer un precio equivocado -- ver
// server/services/orderPricing.js para el detalle del bug de origen.
const pizzaSizes = (Array.isArray(sizesRaw) ? sizesRaw : [])
  .filter(s => s.activo !== false && !String(s.id).startsWith('psz_'))
  .sort((a, b) => a.precio - b.precio)
  .map(s => ({ id: s.id, nombre: s.nombre, precio: s.precio }));

const trimmed = {
  categories,
  products,
  variants,
  pizzaSizes,
  combos: menu.combos || [],
  promotions: menu.promotions || [],
  updatedAt: menu.updatedAt,
};

const staticData = this.getWorkflowStaticData('global');
staticData.menuCache = { ts: Date.now(), data: trimmed };

return [{ json: trimmed }];
